import AppKit

/// Makes sure Veil always shows its own icon in the Dock (even when started without the .app bundle).
enum AppIcon {
    static func apply() {
        if let url = Bundle.main.url(forResource: "AppIcon", withExtension: "icns"), let img = NSImage(contentsOf: url) {
            NSApp.applicationIconImage = img
            return
        }
        if let data = Data(base64Encoded: png256), let img = NSImage(data: data) {
            NSApp.applicationIconImage = img
        }
    }

    private static let png256 = ""
}
